import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"23、【剝】 坤下艮上","description":"周易口訣義 - 23、【剝】 坤下艮上","frontmatter":{"title":"23、【剝】 坤下艮上","description":"周易口訣義 - 23、【剝】 坤下艮上"},"headers":[],"relativePath":"classics/koujueyi/025.md","filePath":"classics/koujueyi/025.md"}'),r={name:"classics/koujueyi/025.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_23、【剝】-坤下艮上" tabindex="-1">23、【剝】 坤下艮上 <a class="header-anchor" href="#_23、【剝】-坤下艮上" aria-label="Permalink to “23、【剝】 坤下艮上”">​</a></h1><p>彖曰：剝，剝也，柔變剛也。「不利有攸往」，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。</p><p>象曰：山附於地，剝。上以厚下安宅。</p><p>初六：剝床以足，蔑貞兇。</p><p>象曰：「剝床以足」，以滅下也。</p><p>六二：剝床以辨，蔑貞兇。</p><p>象曰：「剝床以辨」，未有與也。</p><p>六三：剝之無咎。</p><p>象曰：「剝之無咎」，失上下也。</p><p>六四：剝床以膚，兇。</p><p>象曰：「剝床以膚」，切近災也。</p><p>六五：貫魚以宮人寵，無不利。</p><p>象曰：「以宮人寵」，終無尤也。</p><p>上九，碩果不食，君子得輿，小人剝廬。</p><p>象曰：「君子得輿」，民所載也。「小人剝廬」，終不可用也。</p><p>解讀</p><p>「剝，不利有攸往」者，剝，落也。以陰剝陽，以小人損君子，是小人道長，君子道消，小人侵害君子，故君子「不利有攸往」。象曰「山附於地，剝」者，山本高峻，今附於地，是剝落之象也。「上以厚下安宅」者，宅，人居者也。剝之為體，自下而起為「乾」，從初九而至剝也，即是小人在下而起，上侵於君子，君子即可敦厚為德，制伏下人，各令安其居也。</p><p>初六，剝床以足，蔑貞兇。「蔑」，削也。床者，人所安之物也。今剝道自下而起，似侵剝床足，人漸不安處，削除中正之道，所以「兇」也。</p><p>六二，剝床以辨，蔑，貞兇。是床梐之間、床足之上分辨之處也。剝之漸盛，削不已，至於床梐之間、分辨之處，削去正道，正道陵夷，所以「兇」也。</p><p>六三，剝之無咎。眾皆剝陽，唯六三與上九相應，是獨親狎於君子，雖當剝時，可以「無咎」也。</p><p>六四：剝床以膚，兇。床既削盡，以至人膚，身體被其侵剝，切近於災，故為「兇」矣。</p><p>六五：貫魚以宮人寵，無不利者，獨處於尊，為剝之主，眾陰皆歸，駢頭相次，如貫穿之魚。小人得寵，以消君子。若接待眾陰，而似宮人在內，未能害於外政矣。既不預政事，故云「無不利」也。</p><p>上九：碩果不食，君子得輿，小人剝廬者，處剝之上，獨處不落，猶「碩果」之不食。若君子處於此位，似車輿運載下人，令其獲安，故云君子得輿，民所載也。小人處此上位，即侵削下人廬舍，民何以安？故曰「小人不可用為君長」，故曰「小人剝廬，終不可用」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
